def refresh_worker(worker):
    import importlib
    import torch
    from tools.qwen4exp import decode_preparation_graph
    importlib.reload(decode_preparation_graph)
    commit = worker._resident_session().native_resources['qfn_mamba_commit_v4']
    if commit.device_transition_v1.pending is not None or worker.model_runner.execute_model_state is not None:
        raise RuntimeError('drain before changing preparation graphs')
    torch.npu.synchronize()
    owner = getattr(commit, 'decode_preparation_v1', None)
    if 'install' == 'install':
        if owner is not None:
            raise RuntimeError('preparation owner already exists')
        owner = decode_preparation_graph.DecodePreparationGraphs.__new__(decode_preparation_graph.DecodePreparationGraphs)
        commit.decode_preparation_v1 = owner
        owner.__init__(commit)
        owner.construction_complete = True
        owner.install()
        owner.enabled = owner.verify = True
    elif owner is None or not getattr(owner, 'construction_complete', False) or owner.failed:
        raise RuntimeError('missing or failed owner must remain retained')
    elif 'install' != 'status':
        if 'install' == 'on' and (not owner.checked or owner.verification_error):
            raise RuntimeError('successful real packet comparisons required before enabling fast preparation')
        owner.enabled = 'install' != 'off'
        owner.verify = 'install' == 'verify'
    return dict(rank=worker.rank, passed=True, owner=owner.status())

class Candidate:
    def validate(self, engine):
        if not engine._pause_complete() or engine.batch_queue or engine.scheduler.get_num_unfinished_requests():
            raise RuntimeError('drain engine and workers before changing metadata graphs')
        return dict(passed=True)
    def apply(self, engine):
        self.validate(engine)
        rows = engine.model_executor.collective_rpc(refresh_worker)
        return dict(passed=len(rows) == 4 and all(row.get('passed') for row in rows), workers=rows)
def prepare(engine):
    return Candidate()

